using System;
using System.Collections.Generic;
using System.Linq;
using WorkEnv;

public sealed class ScorePoint {
 public string Id,Name,Status,Action;public int Weight;
 public ScorePoint(string id,string name,int weight,string status,string action){Id=id;Name=name;Weight=weight;Status=status;Action=action;}
}
// Measures only the current IPv4/DNS/TLS observations, not privacy or account safety.
public sealed class ScoreAssessment {
 public readonly List<ScorePoint> Points=new List<ScorePoint>();
 public bool Waiting,HasScore;public int Score,UnknownWeight,Normal,Unknown,Abnormal;public string Level,Conclusion,Action,Headline,CoreStatus;public Report EffectiveReport;
 public static bool IsFresh(Item i,DateTimeOffset now,IEnumerable<string> historical){if(i==null)return false;DateTimeOffset at;if(!DateTimeOffset.TryParse(i.observedAt,out at))return false;double age=(now-at).TotalSeconds;return age>=0&&age<(i.key.StartsWith("ext-")||i.key.StartsWith("demo-view-")?300:30)&&!(historical??new string[0]).Contains(i.key);}
 static Item StaleCopy(Item i){return new Item(i.key,"unknown",i.source,i.observation,i.limitation,i.next){observedAt=i.observedAt,subject=i.subject,role=i.role,identity=i.identity,serviceEvidence=i.serviceEvidence,evidencePhase=i.evidencePhase,evidenceScope=i.evidenceScope,failureCode=i.failureCode,rawResult=i.rawResult,transportState="unknown"};}
 public static Report Project(Report report,bool demo,DateTimeOffset now,IEnumerable<string> historical){return new Report{items=report.items.Where(i=>i!=null&&(demo||!i.key.StartsWith("demo-view-"))).Select(i=>IsFresh(i,now,historical)?i:StaleCopy(i)).ToList()};}
 public static string HttpLabel(Item i){if(i==null)return "HTTP 未验证";switch(i.subject){case "http-401":return "HTTP 401：需要认证";case "http-403":return "HTTP 403：访问受限";case "http-404":return "HTTP 404：根路径未提供资源";case "http-421":return "HTTP 421：探针请求未被接受";case "http-429":return "HTTP 429：请求限流";}if(i.subject!=null&&i.subject.StartsWith("http-5"))return "HTTP "+i.subject.Substring(5)+"：服务返回错误";if(i.subject!=null&&i.subject.StartsWith("http-"))return "HTTP "+i.subject.Substring(5)+"：已响应";return "HTTP 未完成";}
 public static string HttpShort(Item i){if(i==null)return "HTTP 未完成";switch(i.subject){case "http-401":return "401 需认证";case "http-403":return "403 访问受限";case "http-404":return "404 根路径无资源";case "http-421":return "421 请求未接受";case "http-429":return "429 请求限流";}if(i.subject!=null&&i.subject.StartsWith("http-5"))return i.subject.Substring(5)+" 服务错误";if(i.subject!=null&&i.subject.StartsWith("http-"))return i.subject.Substring(5)+" 已响应";return "HTTP 未完成";}
 public static string ServiceAction(IEnumerable<Item> input){var values=input.ToList();if(values.Count==0)return null;if(values.Any(i=>i.subject=="http-421"))return "探针请求未被服务器接受；请在对应 AI 工具中核对实际响应。";if(values.Any(i=>i.subject=="http-429"))return "服务提示请求频繁，请稍后在对应 AI 工具重试。";if(values.Any(i=>i.subject=="http-403"))return "服务返回访问限制，请在对应 AI 工具核对权限。";if(values.Any(i=>i.identity=="ai-stage-DNS"))return "对应服务域名解析未完成，请检查 DNS。";if(values.Any(i=>i.identity=="ai-stage-TLS"))return "对应服务的加密连接未完成，请检查连接与证书。";if(values.Any(i=>i.identity=="ai-stage-TCP"))return "对应服务连接未完成，请重试连接检查。";return "请在对应 AI 工具中核对登录和实际响应。";}
 public static ScoreAssessment Evaluate(Report report,bool demo,DateTime baselineAt,DateTimeOffset now,IEnumerable<string> historical){var result=new ScoreAssessment();if(report==null||report.items==null){result.Waiting=true;return result;}var old=new HashSet<string>(historical??new string[0]);var items=report.items.Where(i=>i!=null&&(demo||!i.key.StartsWith("demo-view-"))).ToList();double age=(now.LocalDateTime-baselineAt).TotalSeconds;if(baselineAt==DateTime.MinValue||age<0||age>=30)foreach(var i in items.Where(x=>!x.key.StartsWith("ext-")&&!x.key.StartsWith("demo-view-")))old.Add(i.key);result.EffectiveReport=Project(report,demo,now,old);Func<Item,bool> fresh=i=>IsFresh(i,now,old);Func<Item,string> state=i=>!fresh(i)?"unknown":i.status=="attention"?"attention":i.status=="pass"?"pass":"unknown";
  Func<string,string,string> get=delegate(string real,string fake){string key=demo&&fake!=null?"demo-view-"+fake:real;var found=items.Where(i=>i.key==key).ToList();if(found.Count==0)return "unknown";var s=found.Select(i=>demo&&fake!=null&&fresh(i)?(i.role=="pass"?"pass":i.role=="attention"?"attention":"unknown"):state(i)).ToList();return s.Contains("attention")?"attention":s.Contains("unknown")?"unknown":"pass";};
  var sources=items.Where(i=>i.key=="ipv4-source").ToList();var groups=sources.Where(i=>!String.IsNullOrWhiteSpace(i.source)).GroupBy(i=>i.source,StringComparer.OrdinalIgnoreCase).ToList();string comparison=get("ipv4-compare",null);string v4=groups.Count==2&&groups.All(g=>g.All(i=>state(i)=="pass"))&&comparison=="pass"?"pass":comparison=="attention"||sources.Any(i=>state(i)=="attention")?"attention":"unknown";var expected=items.Where(i=>i.key=="ipv4-expected").ToList();bool disabled=expected.Count>0&&expected.All(i=>fresh(i)&&i.status=="not-applicable");result.Points.Add(new ScorePoint("exit-consistency","IPv4 双源一致",disabled?30:25,v4,"请核对两个 IPv4 出口后重新检查。"));if(!disabled)result.Points.Add(new ScorePoint("exit-expected","固定 IPv4 核对",5,get("ipv4-expected",null),"请核对固定 IPv4 设置和当前连接。"));result.Points.Add(new ScorePoint("dns-lookup","DNS 解析",10,get("ext-dns-lookup","dns"),"请检查域名解析后重试。"));
  foreach(var spec in new[]{new[]{"claude","Claude","ext-ai-claude"},new[]{"openai","Codex / OpenAI","ext-ai-openai"},new[]{"grok","Grok","ext-ai-grok"}}){string key=demo?"demo-view-"+spec[0]:spec[2];var found=items.Where(i=>i.key==key).ToList();var states=found.Select(i=>!fresh(i)?"unknown":demo?(i.role=="pass"?"pass":i.role=="attention"?"attention":"unknown"):(i.transportState=="attention"||(i.failureCode??"").StartsWith("certificate-")?"attention":i.transportState=="pass"?"pass":"unknown")).ToList();string transport=states.Count==0?"unknown":states.Contains("attention")?"attention":states.Contains("unknown")?"unknown":"pass";result.Points.Add(new ScorePoint("ai-"+spec[0],spec[1],20,transport,transport=="attention"?"请先核对 "+spec[1]+" 的证书与连接。":"请重试 "+spec[1]+" 的连接检查。"));}
  result.Score=result.Points.Where(p=>p.Status=="pass").Sum(p=>p.Weight);result.UnknownWeight=result.Points.Where(p=>p.Status=="unknown").Sum(p=>p.Weight);result.Normal=result.Points.Count(p=>p.Status=="pass");result.Unknown=result.Points.Count(p=>p.Status=="unknown");result.Abnormal=result.Points.Count(p=>p.Status=="attention");bool incomplete=items.Any(i=>i.key=="check"&&state(i)!="pass");result.HasScore=result.UnknownWeight==0;result.Waiting=result.Normal==0&&result.Abnormal==0;result.CoreStatus=v4;var fixedPoint=result.Points.FirstOrDefault(p=>p.Id=="exit-expected");var cert=result.Points.FirstOrDefault(p=>p.Id.StartsWith("ai-")&&p.Status=="attention");var servicePoints=result.Points.Where(p=>p.Id.StartsWith("ai-")).ToList();var available=servicePoints.Where(p=>p.Status=="pass").Select(p=>p.Name).ToArray();var unavailable=servicePoints.Where(p=>p.Status!="pass").Select(p=>p.Name).ToArray();bool endpointMismatch=items.Any(i=>fresh(i)&&((i.key=="ext-rtc-compare"||i.key=="ipv6-path"||i.key=="ipv6-public")&&i.status=="attention"));bool extraV6=!disabled&&items.Any(i=>fresh(i)&&i.key=="ipv6-public"&&i.status=="pass");
  if(fixedPoint!=null&&fixedPoint.Status=="attention"||v4=="attention"){result.Level="red";result.Headline="出口与预期不同，先核对连接";result.Conclusion=result.Headline;result.Action="请核对本轮 IPv4 出口与固定设置，再重新检查。";}
  else if(cert!=null){result.Level="red";result.Headline="证书验证异常，先核对连接";result.Conclusion=result.Headline;result.Action=cert.Action;}
  else if(endpointMismatch){result.Level="red";result.Headline="观察到不同出口，请核对路径";result.Conclusion=result.Headline;result.Action="请查看 IPv6 或浏览器卡片中观察到的差异。";}
  else if(items.Any(i=>fresh(i)&&i.key=="ipv6-public"&&i.status=="pass")&&items.Any(i=>fresh(i)&&i.key=="ipv6-path"&&i.status=="pass"&&(i.identity=="ipv6-path-no-path"||i.identity=="ipv6-path-blocked"))){result.Level="yellow";result.Headline="IPv6 路径观察存在冲突，请核对";result.Conclusion=result.Headline;result.Action="公网 IPv6 观察与本机路径结果不一致，请重新检查对应卡片。";}
  else if(fixedPoint!=null&&fixedPoint.Status=="unknown"){result.Level="yellow";result.Headline="固定 IPv4 尚未确认";result.Conclusion=result.Headline;result.Action="请补全或核对固定 IPv4 设置，再重新检查。";}
  else if(available.Length==0){result.Level="yellow";result.Headline="暂未确认 AI 服务连接，请重试连接检查";result.Conclusion=result.Headline;result.Action="登录和模型响应仍需在对应工具中单独验证。";}
  else if(disabled&&v4=="unknown"&&!incomplete&&get("ext-dns-lookup","dns")=="pass"&&groups.Count==2&&groups.Count(g=>g.All(i=>state(i)=="pass"))==1){result.Level="yellow";result.Headline="AI 连接已建立，出口核验待重试";result.Conclusion=result.Headline;result.Action="已建立加密连接："+String.Join("、",available)+"；可在对应工具中试用。另一个 IPv4 观察源未完成，可稍后重试；登录和模型响应仍需分别验证。";}
  else if(v4!="pass"||get("ext-dns-lookup","dns")!="pass"||incomplete){result.Level="yellow";result.Headline="部分连接已建立，仍需核对网络";result.Conclusion=result.Headline;result.Action="已建立加密连接："+String.Join("、",available)+"；请检查 IPv4 和 DNS 后重试。";}
  else{result.Level=extraV6?"yellow":"green";result.Headline=extraV6?"网络连接正常，另有 IPv6 出口待核对":"网络连接正常，可以开始办公";result.Conclusion=result.Headline;result.Action="已建立加密连接："+String.Join("、",available)+(unavailable.Length>0?"；待确认："+String.Join("、",unavailable):"")+(disabled?"；本轮 IPv4 双源一致":"；本轮固定 IPv4 核对通过")+(extraV6?"；观察到额外公网 IPv6，请核对其路径":"")+"。登录和模型响应仍需分别验证。";}
  return result;
 }
 public string Details(){if(Waiting)return "等待本轮连通证据。";return "网络连通得分：已确认 "+Score+" 分，另 "+UnknownWeight+" 分待测。\r\n"+String.Join("\r\n",Points.Select(p=>p.Name+" · "+p.Status+" · 权重 "+p.Weight).ToArray());}
}
